import moment from 'moment';

// Pure helpers of the Mentor calls report page (views/admin/Reports/MentorCallsReportPage).

export const PERIODS = [
  { value: 'DAY', label: 'Day' },
  { value: 'WEEK', label: 'Week' },
  { value: 'MONTH', label: 'Month' },
  { value: 'YEAR', label: 'Year' },
  { value: 'CUSTOM', label: 'Date range' },
];

export const CALL_STATUSES = {
  PENDING: { label: 'Not called yet', tone: 'neutral' },
  CONNECTED: { label: 'Spoke to guardian', tone: 'good' },
  NOT_REACHABLE: { label: 'Could not reach', tone: 'bad' },
  CALL_BACK_LATER: { label: 'Call back later', tone: 'warn' },
};
export const QUERY_STATUSES = {
  NONE: { label: 'No question', tone: 'neutral' },
  OPEN: { label: 'Not answered yet', tone: 'bad' },
  RESOLVED: { label: 'Answered', tone: 'good' },
};

export const callStatusLabel = status => CALL_STATUSES[status]?.label || status || '--';
export const callStatusTone = status => CALL_STATUSES[status]?.tone || 'neutral';
export const queryStatusLabel = status => QUERY_STATUSES[status]?.label || status || '--';
export const queryStatusTone = status => QUERY_STATUSES[status]?.tone || 'neutral';

export const defaultPeriod = () => {
  const today = moment().format('YYYY-MM-DD');
  return {
    type: 'DAY',
    date: today,
    month: moment().format('YYYY-MM'),
    year: String(moment().year()),
    from: moment().startOf('month').format('YYYY-MM-DD'),
    to: today,
  };
};

// What is missing before a report can be asked for, or '' when it is ready.
export const periodProblem = ({ type, date, month, year, from, to }) => {
  if ((type === 'DAY' || type === 'WEEK') && !date) return 'Pick the date.';
  if (type === 'MONTH' && !month) return 'Pick the month.';
  if (type === 'YEAR' && !/^\d{4}$/.test(String(year || ''))) return 'Type the year, for example 2026.';
  if (type === 'CUSTOM') {
    if (!from || !to) return 'Pick both the from and the to date.';
    if (from > to) return 'The from date is after the to date.';
  }
  return '';
};

// The period part of a report query: only the fields the chosen period uses.
export const periodParams = ({ type, date, month, year, from, to }) => ({
  type,
  ...((type === 'DAY' || type === 'WEEK') && { date }),
  ...(type === 'MONTH' && { month }),
  ...(type === 'YEAR' && { year }),
  ...(type === 'CUSTOM' && { from, to }),
});

// The call list: period + the optional filters + the page. `size` falls back to 20.
export const reportParams = ({ schoolId, period, filters = {}, page = 1, size = 20 }) => ({
  schoolId,
  ...periodParams(period),
  employeeId: filters.employeeId,
  courseId: filters.courseId,
  studentId: filters.studentId,
  callStatus: filters.callStatus,
  queryStatus: filters.queryStatus,
  page,
  size,
});

// The per-teacher counts take only the school, the period and the teacher.
export const summaryParams = ({ schoolId, period, filters = {} }) => ({
  schoolId,
  ...periodParams(period),
  employeeId: filters.employeeId,
});

// "09 Nov to 11 Nov 2026" for a range the backend answered with.
export const rangeLabel = (from, to) => {
  if (!from) return '';
  if (!to || from === to) return moment(from).format('DD MMM YYYY');
  return `${moment(from).format('DD MMM YYYY')} to ${moment(to).format('DD MMM YYYY')}`;
};

// "Mr Raj (father) - 9999999999" style line for a call's guardian; missing parts are left out.
export const guardianLine = call =>
  [
    call?.guardianName && `${call.guardianName}${call.guardianRelation ? ` (${call.guardianRelation})` : ''}`,
    call?.guardianMobile,
  ]
    .filter(Boolean)
    .join(' - ');

// ---- the teacher's day (record calls, wishlist) -------------------------------------------------------------------------------

// What can be recorded for a call (a call that is not made yet stays PENDING by itself).
export const LOGGABLE_STATUSES = ['CONNECTED', 'NOT_REACHABLE', 'CALL_BACK_LATER'];

// A call that is not made yet can be removed; one that is recorded can only be edited.
export const isPending = call => !call || call.callStatus === 'PENDING';

// "3 mentees today, 1 call recorded": calls that are not pending any more are the recorded ones.
export const todayCounts = calls => {
  const list = calls || [];
  const done = list.filter(call => !isPending(call)).length;
  return { total: list.length, done, left: list.length - done };
};

// A phone number for a tel: link: digits and a leading +. Empty when there is nothing to dial.
export const dialNumber = mobile =>
  String(mobile || '')
    .replace(/[^\d+]/g, '')
    .replace(/(?!^)\+/g, '');

// The form of a call that is opened to record or edit it.
export const formOfCall = call => ({
  callStatus: LOGGABLE_STATUSES.includes(call?.callStatus) ? call.callStatus : 'CONNECTED',
  feedback: call?.feedback || '',
  queries: call?.queries || '',
  queryStatus: call?.queries ? call.queryStatus || 'OPEN' : '',
  resolution: call?.resolution || '',
  followUpDate: call?.followUpDate || '',
});

// The body of "save the call": empty fields are left out, and a query status is sent only with a query (the backend picks OPEN for
// a typed query and NONE for none).
export const logBody = form => {
  const body = {
    callStatus: form.callStatus,
    feedback: (form.feedback || '').trim(),
    queries: (form.queries || '').trim(),
    queryStatus: (form.queries || '').trim() ? form.queryStatus : '',
    resolution: form.queryStatus === 'RESOLVED' ? (form.resolution || '').trim() : '',
    followUpDate: form.followUpDate,
  };
  return Object.fromEntries(
    Object.entries(body).filter(([, value]) => value !== undefined && value !== null && value !== '')
  );
};
