import React, { useState } from 'react';
import { Modal, ModalBody, ModalFooter, ModalHeader } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';

const LIMIT = 140;

// A text that can be very long (a call's feedback or a guardian's query, up to 2000 characters): the first few lines in the list, and
// "Read full" opens the whole text in a box of its own, so a long note never stretches the list. Short text is shown as it is.
const ClampedText = ({ text, title = 'Full text', lines = 3, style }) => {
  const [open, setOpen] = useState(false);
  if (!text) return null;
  const long = text.length > LIMIT;
  return (
    <div style={{ wordBreak: 'break-word', whiteSpace: 'pre-wrap', ...style }}>
      <div
        style={
          long
            ? { display: '-webkit-box', WebkitLineClamp: lines, WebkitBoxOrient: 'vertical', overflow: 'hidden' }
            : undefined
        }>
        {text}
      </div>
      {long && (
        <a
          style={{ cursor: 'pointer', fontSize: 12, fontWeight: 'bold', color: colors.aTag }}
          onClick={() => setOpen(true)}>
          Read full
        </a>
      )}
      <Modal isOpen={open} toggle={() => setOpen(false)} centered scrollable>
        <ModalHeader toggle={() => setOpen(false)}>{title}</ModalHeader>
        <ModalBody style={{ whiteSpace: 'pre-wrap', wordBreak: 'break-word', fontSize: 14, lineHeight: 1.6 }}>
          {text}
        </ModalBody>
        <ModalFooter style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: 12 }}>
          <CustomButton name="Close" onClick={() => setOpen(false)} />
        </ModalFooter>
      </Modal>
    </div>
  );
};

export default ClampedText;
