import axios from 'axios';
import constants from '../../config/constants';

// Mentor calls: a teacher calls a student's guardian and records how it went (the process: Today / Wishlist), and the school
// reads it back (the report: every call with its feedback, query and follow-up, and per-teacher counts). The same calls can be
// made on the phone (the mobile app) or here. Today, recording and the wishlist work on the logged-in user's own calls; a teacher
// sees only their own calls in the report, an admin everyone's.
const BASE = `${constants.API_BASE_URL}/api/employee/mentor-calls`;

// The query string drops every field that is empty, so an unset filter is not sent at all.
const clean = params =>
  Object.fromEntries(
    Object.entries(params).filter(([, value]) => value !== undefined && value !== null && value !== '')
  );

// -> { type, from, to, page, size, totalElements, totalPages, items: [call] }; page is 1-based.
export const fetchMentorCallReportApi = ({ token, params }) =>
  axios.get(`${BASE}/report${constants.makeParams(clean(params))}`, constants.setHeader(token)).then(res => res.data);

// -> { type, from, to, total, pending, connected, notReachable, callBackLater, openQueries, teachers: [per-teacher counts] }
export const fetchMentorCallSummaryApi = ({ token, params }) =>
  axios
    .get(`${BASE}/report/summary${constants.makeParams(clean(params))}`, constants.setHeader(token))
    .then(res => res.data);

// ---- the teacher's day -------------------------------------------------------------------------------------------------------

const get = (path, token) => axios.get(`${BASE}${path}`, constants.setHeader(token)).then(res => res.data);

// Today's mentees, topped up to the daily count the first time it is opened. -> [call]
export const fetchTodayApi = ({ token, schoolId, batchId }) =>
  get(`/today${constants.makeParams(clean({ schoolId, batchId }))}`, token);

// Add a student to a day's list (callDate empty = today).
export const assignStudentApi = ({ token, schoolId, studentId, callDate }) =>
  axios
    .post(`${BASE}/assign`, clean({ schoolId, studentId, callDate }), constants.setHeader(token))
    .then(res => res.data);

// How the call went. Replaces the earlier outcome of that call.
export const logCallApi = ({ token, callId, body }) =>
  axios.put(`${BASE}/${callId}/log`, body, constants.setHeader(token)).then(res => res.data);

// Only a call that is still pending can be removed; a new mentee is given in its place the next time today is opened.
export const deleteCallApi = ({ token, callId }) => axios.delete(`${BASE}/${callId}`, constants.setHeader(token));

// -> { page, size, totalElements, totalPages, items }; page is 1-based.
export const fetchWishlistApi = ({ token, status, page, size }) =>
  get(`/wishlist${constants.makeParams(clean({ status, page, size }))}`, token);

export const addWishlistApi = ({ token, schoolId, studentId, note, remindDate }) =>
  axios
    .post(`${BASE}/wishlist`, clean({ schoolId, studentId, note, remindDate }), constants.setHeader(token))
    .then(res => res.data);

// body: { note, remindDate, status: 'ACTIVE' | 'DONE' }
export const updateWishlistApi = ({ token, wishlistId, body }) =>
  axios.put(`${BASE}/wishlist/${wishlistId}`, clean(body), constants.setHeader(token)).then(res => res.data);

export const removeWishlistApi = ({ token, wishlistId }) =>
  axios.delete(`${BASE}/wishlist/${wishlistId}`, constants.setHeader(token));

// "Call now": puts the wishlisted student on today's list.
export const scheduleWishlistApi = ({ token, wishlistId }) =>
  axios.post(`${BASE}/wishlist/${wishlistId}/schedule`, null, constants.setHeader(token)).then(res => res.data);

// The class and student pickers of "add a student".
export const fetchCourseStudentsApi = ({ token, courseId, batchId }) =>
  axios
    .get(`${constants.API_BASE_URL}/api/employee/course-students/${courseId}/${batchId}`, constants.setHeader(token))
    .then(res => res.data || []);

// The classes to pick from: a teacher sees the classes they are assigned to, an admin every class of the batch. -> [course]
export const fetchPickerCoursesApi = ({ token, isTeacher, employeeId, batchId }) =>
  axios
    .get(
      isTeacher
        ? `${constants.API_BASE_URL}/api/employee/course/${employeeId}/${batchId}`
        : `${constants.API_BASE_URL}/api/admin/get-course-for-batch/${batchId}`,
      constants.setHeader(token)
    )
    .then(res => res.data || []);
