import React from 'react';
import Paper from '@material-ui/core/Paper';
import TableCell from '@material-ui/core/TableCell';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';

// The pieces every Reports / list page is built from (the look of the Transport reports): a plain white panel with a bold dark-purple
// heading and the page's own action (Export Excel, Add ...) on the right, small grey bold table headings, and a "1 - 25 of 80" pager
// with Prev / Next. Summary tiles go above the panel.

export const ReportPaper = ({ title, intro, action, children, style }) => (
  <Paper square style={{ padding: 16, marginBottom: 16, ...style }}>
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        flexWrap: 'wrap',
        gap: 8,
        marginBottom: intro ? 2 : 8,
      }}>
      <b style={{ color: colors.accentDark }}>{title}</b>
      {action && <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>{action}</div>}
    </div>
    {intro && <div style={{ fontSize: 12, color: '#7d7d7d', marginBottom: 8 }}>{intro}</div>}
    {children}
  </Paper>
);

export const HeadCell = ({ children, align, style }) => (
  <TableCell align={align} style={{ color: '#7d7d7d', fontSize: 12, whiteSpace: 'nowrap', ...style }}>
    <b>{children}</b>
  </TableCell>
);

// from / to are 1-based positions of the rows shown; onPrev / onNext are called when a button is pressed.
export const Pager = ({ from, to, total, hasPrev, hasNext, onPrev, onNext, disabled }) => (
  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: 8, marginTop: 12 }}>
    <span style={{ fontSize: 12, color: '#7d7d7d' }}>
      {from} - {to} of {total}
    </span>
    <CustomButton
      size="small"
      variant="outlined"
      color="default"
      name="Prev"
      disabled={disabled || !hasPrev}
      onClick={onPrev}
    />
    <CustomButton
      size="small"
      variant="outlined"
      color="default"
      name="Next"
      disabled={disabled || !hasNext}
      onClick={onNext}
    />
  </div>
);
